class Statement {
  constructor(statement) { this.statement = statement; this.values = []; }
  bind(...values) { this.values = values; return this; }
  async run() { const result = this.statement.run(...this.values); return { meta: { changes: Number(result.changes || 0) } }; }
  async first() { return this.statement.get(...this.values) || null; }
  async all() { return { results: this.statement.all(...this.values) }; }
}
class D1 {
  constructor() {
    this.sqlite = new DatabaseSync(":memory:");
    this.sqlite.exec("PRAGMA foreign_keys=ON");
    for (const file of ["0001_finance_core.sql", "0002_partner_portal.sql", "0009_production_admin_auth.sql", "0010_merchant_settlements.sql"]) this.sqlite.exec(readFileSync(new URL(`../migrations/${file}`, import.meta.url), "utf8"));
    this.sqlite.prepare("INSERT INTO merchants(id,merchant_code,name,status) VALUES ('merchant_b','B','商家 B','active')").run();
  }
  prepare(sql) { return new Statement(this.sqlite.prepare(sql)); }
  async batch(statements) { this.sqlite.exec("BEGIN IMMEDIATE"); try { const results = []; for (const statement of statements) results.push(await statement.run()); this.sqlite.exec("COMMIT"); return results; } catch (error) { this.sqlite.exec("ROLLBACK"); throw error; } }
}

const merchantId = "merchant_meiling_001";
const baseProfile = { enabled: true, payment_plan: "upfront_18000", deposit_rate_bp: 3000, platform_fee_rate_bp: 200, processing_fee_mode: "actual_or_estimated", processing_fee_basis: "deposit_collected", estimated_processing_fee_rate_bp: 275, tax_reserve_mode: "disabled", tax_reserve_rate_bp: 0, withholding_mode: "disabled", withholding_rate_bp: 0, refund_platform_fee_policy: "pro_rata_reverse", refund_offset_policy: "pro_rata_reverse", provider_fee_refund_policy: "no_reverse", offset_target_amount_minor: 1_800_000, continue_platform_fee_after_offset: false, settlement_day: 10, legal_review_status: "approved", accounting_review_status: "pending", effective_from: "2026-08-01" };
const calculate = (overrides = {}) => calculateSettlement({ profile: { ...baseProfile, ...overrides.profile }, total_order_amount_minor: overrides.total_order_amount_minor ?? 1_000_000, actual_processing_fee_minor: overrides.actual_processing_fee_minor, actual_deposit_collected_minor: overrides.actual_deposit_collected_minor, prior_offset_amount_minor: overrides.prior_offset_amount_minor ?? 0, adjustments_minor: overrides.adjustments_minor ?? 0, sources: overrides.sources });
function seedProfile(db, id = merchantId, plan = "upfront_18000", overrides = {}) { db.sqlite.prepare(`INSERT INTO merchant_settlement_profiles(id,merchant_id,enabled,payment_plan,deposit_rate_bp,platform_fee_rate_bp,processing_fee_mode,processing_fee_basis,estimated_processing_fee_rate_bp,legal_review_status,effective_from,refund_platform_fee_policy,refund_offset_policy,provider_fee_refund_policy) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(`profile-${id}`, id, 1, plan, 3000, 200, overrides.processing_fee_mode || "actual_or_estimated", "deposit_collected", 275, "approved", "2026-08-01", overrides.refund_platform_fee_policy || "pro_rata_reverse", overrides.refund_offset_policy || "pro_rata_reverse", overrides.provider_fee_refund_policy || "no_reverse"); }
function seedStatement(db, { id = "statement-1", merchant = merchantId, status = "draft", start = "2026-08-01", end = "2026-08-31", payable = 10000, variance = 0, actual = 0, platformFee = 0, offset = 0, processingFee = 0 } = {}) { db.sqlite.prepare(`INSERT INTO merchant_settlements(id,statement_no,merchant_id,profile_id,period_start,period_end,period_start_utc,period_end_exclusive_utc,status,merchant_payable_minor,deposit_variance_minor,actual_deposit_collected_minor,platform_service_fee_minor,current_offset_amount_minor,processing_fee_minor,calculation_version,rules_snapshot_json,locked_at,paid_at,transfer_amount_minor,transfer_reference,voided_at,void_reason) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(id, `NO-${id}`, merchant, `profile-${merchant}`, start, end, taipeiDateToUtcStart(start), taipeiDateToUtcEndExclusive(end), status, payable, variance, actual, platformFee, offset, processingFee, "settlement-v3", "{\"calculation_version\":\"settlement-v3\"}", ["locked", "paid"].includes(status) ? "2026-09-01T00:00:00Z" : null, status === "paid" ? "2026-09-01T01:00:00Z" : null, status === "paid" ? payable : null, status === "paid" ? "TX" : null, status === "void" ? "2026-09-01T00:00:00Z" : null, status === "void" ? "void test" : null); }
function seedPayment(db, { suffix = "1", merchant = merchantId, source = "webhook", status = "paid", gross = 3000, fee = 30, paidAt = "2026-08-31T15:59:59.000Z", orderCurrency = "TWD", paymentCurrency = "TWD" } = {}) { const orderId = `order-${suffix}`, paymentId = `payment-${suffix}`; db.sqlite.prepare("INSERT INTO orders(id,order_no,merchant_id,title,amount_due,currency,payment_status) VALUES (?,?,?,?,?,?,?)").run(orderId, `ORD-${suffix}`, merchant, "訂單", 10000, orderCurrency, "paid"); db.sqlite.prepare("INSERT INTO payments(id,payment_no,merchant_id,order_id,gross_amount,fee_amount,net_amount,amount,currency,payment_method,status,paid_at,source) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)").run(paymentId, `PAY-${suffix}`, merchant, orderId, gross, fee, gross - (fee || 0), gross, paymentCurrency, "card", status, paidAt, source); return { orderId, paymentId }; }
function qualify(db, payment, { role = "platform_deposit", eligible = 1, orderTotal = 1_000_000, expected = 300_000, actual = 300_000, fee = 3000, occurredAt = "2026-08-31T15:59:59.000Z", reserved = null } = {}) { db.sqlite.prepare(`INSERT INTO merchant_settlement_sources(id,merchant_id,payment_id,order_id,collection_role,settlement_eligible,order_total_amount_minor,expected_deposit_amount_minor,actual_collected_amount_minor,provider_fee_actual_minor,occurred_at,reviewed_by,reviewed_at,reserved_statement_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).run(`source-${payment.paymentId}`, merchantId, payment.paymentId, payment.orderId, role, eligible, orderTotal, expected, actual, fee, occurredAt, eligible ? "admin" : null, eligible ? "2026-08-01T00:00:00Z" : null, reserved); }
const req = (path, method = "GET", body = {}, key = null) => new Request(`https://worker.test/api/finance${path}`, { method, headers: { "content-type": "application/json", ...(key ? { "idempotency-key": key } : {}) }, ...(method === "GET" ? {} : { body: JSON.stringify({ ...body, ...(key ? { idempotency_key: key } : {}) }) }) });

