async function authEnv() { const db = new D1(); const salt = "admin-salt"; const hash = await deriveAdminPassword("A-secure-admin-password-2026", salt); db.sqlite.prepare("INSERT INTO admin_users(id,email,display_name,password_hash,password_salt,role) VALUES ('admin','owner@example.com','管理員',?,?,'super_admin')").run(hash, salt); return { db, env: { FINANCE_DB: db, ALLOWED_ORIGINS: "https://baiyeconnect.com", CONTRACTS_BUCKET: { async get() { return null; }, async put() {}, async delete() {} } } }; }
async function login(env) { const request = new Request("https://worker.test/api/admin/auth/login", { method: "POST", headers: { origin: "https://baiyeconnect.com", "content-type": "application/json" }, body: JSON.stringify({ email: "owner@example.com", password: "A-secure-admin-password-2026" }) }); const response = await worker.fetch(request, env, {}); const body = await response.json(); return { cookie: response.headers.get("set-cookie").split(";")[0], csrf: body.csrf_token }; }
test("RC2-38 未登入 Admin 仍回 401", async () => { const { env } = await authEnv(); const response = await worker.fetch(new Request("https://worker.test/api/finance/settlements", { headers: { origin: "https://baiyeconnect.com" } }), env, {}); assert.equal(response.status, 401); });
test("RC2-39 缺 CSRF mutation 被拒絕", async () => { const { env } = await authEnv(); const session = await login(env); const response = await worker.fetch(new Request("https://worker.test/api/finance/settlements/preview", { method: "POST", headers: { origin: "https://baiyeconnect.com", cookie: session.cookie, "content-type": "application/json" }, body: "{}" }), env, {}); assert.equal(response.status, 401); });
test("RC2-40 非正式 Origin 被拒絕", async () => { const { env } = await authEnv(); const response = await worker.fetch(new Request("https://worker.test/api/finance/settlements", { headers: { origin: "https://evil.example" } }), env, {}); assert.equal(response.status, 403); });
test("RC2-41 PDF 未授權不得下載", async () => { const { env } = await authEnv(); const response = await worker.fetch(new Request("https://worker.test/api/finance/settlements/secret/pdf", { headers: { origin: "https://baiyeconnect.com" } }), env, {}); assert.equal(response.status, 401); });

test("RC3-1 同一訂單兩筆合格訂金被 DB 拒絕", () => { const db=new D1(); seedProfile(db); const first=seedPayment(db,{suffix:"same-a"}); qualify(db,first); const secondId="payment-same-b"; db.sqlite.prepare("INSERT INTO payments(id,payment_no,merchant_id,order_id,gross_amount,net_amount,amount,payment_method,status,paid_at,source) VALUES (?,?,?,?,1500,1500,1500,'card','paid','2026-08-01','webhook')").run(secondId,"PAY-SAME-B",merchantId,first.orderId); assert.throws(()=>db.sqlite.prepare("INSERT INTO merchant_settlement_sources(id,merchant_id,payment_id,order_id,collection_role,settlement_eligible,order_total_amount_minor,expected_deposit_amount_minor,actual_collected_amount_minor,occurred_at,reviewed_by,reviewed_at) VALUES ('second',?,?,?,'platform_deposit',1,1000000,300000,150000,'2026-08-01','admin','2026-08-01')").run(merchantId,secondId,first.orderId),/UNIQUE/); });
test("RC3-2 計算引擎阻止同訂單重複平台費", () => assert.throws(()=>calculate({sources:[{order_id:"same",order_total_amount_minor:1_000_000,expected_deposit_amount_minor:300_000,actual_collected_amount_minor:150_000,provider_fee_actual_minor:0},{order_id:"same",order_total_amount_minor:1_000_000,expected_deposit_amount_minor:300_000,actual_collected_amount_minor:150_000,provider_fee_actual_minor:0}]}),/同一訂單/));
test("RC3-3 Offset Ledger 三期維持 8,500", () => { const db=new D1(); seedProfile(db,merchantId,"sales_offset_18000"); const sql="INSERT INTO merchant_offset_ledger(id,merchant_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES (?,?,?,?,?,?,?)"; db.sqlite.prepare(sql).run("aug",merchantId,"offset_earned",1_000_000,"2026-08-31","aug","admin"); db.sqlite.prepare(sql).run("sep-r",merchantId,"refund_reversal",-200_000,"2026-09-05","sep-r","admin"); db.sqlite.prepare(sql).run("sep-e",merchantId,"offset_earned",50_000,"2026-09-30","sep-e","admin"); assert.equal(db.sqlite.prepare("SELECT SUM(amount_minor) balance FROM merchant_offset_ledger WHERE merchant_id=? AND status='posted'").get(merchantId).balance,850_000); });
test("RC3-4 回沖後抵付不會被歷史 MAX 復活", () => { const db=new D1(); seedProfile(db,merchantId,"sales_offset_18000"); db.sqlite.exec(`INSERT INTO merchant_offset_ledger(id,merchant_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES ('a','${merchantId}','offset_earned',1000000,'2026-08-31','a','admin'); INSERT INTO merchant_offset_ledger(id,merchant_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES ('b','${merchantId}','refund_reversal',-200000,'2026-09-05','b','admin');`); assert.equal(db.sqlite.prepare("SELECT SUM(amount_minor) n FROM merchant_offset_ledger").get().n,800000); });
test("RC3-5 跨月退款在原單仍 draft 時建立九月 Adjustment", async()=>{ const db=new D1();seedProfile(db);seedStatement(db);const p=seedPayment(db,{paidAt:"2026-08-25T04:00:00Z"});db.sqlite.prepare("INSERT INTO merchant_settlement_items(id,settlement_id,merchant_id,item_type,source_type,source_id,order_id,payment_id,order_total_amount_minor,actual_deposit_amount_minor,processing_fee_minor,amount_minor,occurred_at,source_snapshot_json) VALUES ('cross','statement-1',?,'deposit','payment',?,?,?,1000000,300000,3000,300000,'2026-08-25','{}')").run(merchantId,p.paymentId,p.orderId,p.paymentId);db.sqlite.prepare("INSERT INTO refunds(id,payment_id,amount,status,refunded_at) VALUES ('sep-refund',?,1000,'refunded','2026-09-05T04:00:00Z')").run(p.paymentId);const result=await createSettlementRefundAdjustment(db,{admin_user_id:"admin"},"sep-refund");assert.equal(result.review_status,"approved");const a=db.sqlite.prepare("SELECT effective_date,eligible_period_start,source_refund_id FROM merchant_settlement_adjustments").get();assert.equal(a.effective_date,"2026-09-05");assert.equal(a.eligible_period_start,"2026-09-05");assert.equal(a.source_refund_id,"sep-refund");});
