test("RC3-7 同一 refund 只能有一筆有效 Adjustment",()=>{const db=new D1();seedProfile(db);seedStatement(db,{status:"locked"});const p=seedPayment(db);db.sqlite.prepare("INSERT INTO refunds(id,payment_id,amount,status,refunded_at) VALUES ('same-ref',?,1,'refunded','2026-09-01')").run(p.paymentId);const sql="INSERT INTO merchant_settlement_adjustments(id,merchant_id,source_settlement_id,adjustment_type,amount_minor,reason,effective_date,eligible_period_start,source_refund_id,idempotency_key,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)";db.sqlite.prepare(sql).run("two",merchantId,"statement-1","refund",-1,"r","2026-09-01","2026-09-01","same-ref","two","admin");assert.throws(()=>db.sqlite.prepare(sql).run("three",merchantId,"statement-1","refund",-1,"r","2026-09-01","2026-09-01","same-ref","three","admin"),/UNIQUE/);});
