test("RC3.1-1 Profile、Statement、Snapshot、PDF 與 CSV 統一 settlement-v3", async()=>{const db=new D1();seedProfile(db);assert.equal(db.sqlite.prepare("SELECT calculation_version FROM merchant_settlement_profiles").get().calculation_version,"settlement-v3");const request=req("/settlements","POST",{merchant_id:merchantId,period_start:"2026-08-01",period_end:"2026-08-31"},"calc-v3");const response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,201);const created=await response.json();const statement=db.sqlite.prepare("SELECT * FROM merchant_settlements WHERE id=?").get(created.id);assert.equal(statement.calculation_version,"settlement-v3");assert.equal(JSON.parse(statement.rules_snapshot_json).calculation_version,"settlement-v3");assert.match(new TextDecoder().decode(settlementCsv(statement)),/settlement-v3/);const pdf=await createSettlementPdf({...statement,merchant_name:"測試商家",generated_at:"2026-09-01T00:00:00Z"});const encoded=Array.from("settlement-v3").map((char)=>char.charCodeAt(0).toString(16).padStart(4,"0")).join("").toUpperCase();assert.match(new TextDecoder().decode(pdf.bytes),new RegExp(encoded));});

test("RC3.1-2 Offset Ledger 禁止 UPDATE 與 DELETE",()=>{const db=new D1();seedProfile(db,merchantId,"sales_offset_18000");db.sqlite.prepare("INSERT INTO merchant_offset_ledger(id,merchant_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES ('ledger',?,'offset_earned',100,'2026-08-31','ledger','admin')").run(merchantId);assert.throws(()=>db.sqlite.prepare("UPDATE merchant_offset_ledger SET amount_minor=200 WHERE id='ledger'").run(),/immutable/);assert.throws(()=>db.sqlite.prepare("DELETE FROM merchant_offset_ledger WHERE id='ledger'").run(),/immutable/);});

test("RC3.1-3 抵付目標低於 Ledger 餘額回傳 409",async()=>{const db=new D1();seedProfile(db,merchantId,"sales_offset_18000");db.sqlite.prepare("INSERT INTO merchant_offset_ledger(id,merchant_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES ('ledger',?,'offset_earned',50000,'2026-08-31','ledger','admin')").run(merchantId);const request=req(`/settlement-profiles/${merchantId}`,"PATCH",{...baseProfile,payment_plan:"sales_offset_18000",offset_target_amount_minor:40000});const response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,409);assert.equal((await response.json()).code,"OFFSET_TARGET_BELOW_LEDGER_BALANCE");});

test("RC3.1-4 有 Ledger 時不可直接改為一次付清",async()=>{const db=new D1();seedProfile(db,merchantId,"sales_offset_18000");db.sqlite.prepare("INSERT INTO merchant_offset_ledger(id,merchant_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES ('ledger',?,'offset_earned',50000,'2026-08-31','ledger','admin')").run(merchantId);const request=req(`/settlement-profiles/${merchantId}`,"PATCH",{...baseProfile,payment_plan:"upfront_18000"});const response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,409);assert.equal((await response.json()).code,"PAYMENT_PLAN_SETTLEMENT_REQUIRED");});

test("RC3.1-5 Ledger 跨商家 settlement／adjustment reference 被拒絕",()=>{const db=new D1();seedProfile(db);seedProfile(db,"merchant_b","sales_offset_18000");seedStatement(db,{id:"b-statement",merchant:"merchant_b"});db.sqlite.prepare("INSERT INTO merchant_settlement_adjustments(id,merchant_id,source_settlement_id,adjustment_type,amount_minor,reason,effective_date,eligible_period_start,idempotency_key,created_by) VALUES ('b-adjustment','merchant_b','b-statement','correction',1,'x','2026-09-01','2026-09-01','b','admin')").run();const sql="INSERT INTO merchant_offset_ledger(id,merchant_id,settlement_id,adjustment_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES (?,?,?,?, 'manual_correction',1,'2026-09-01',?,'admin')";assert.throws(()=>db.sqlite.prepare(sql).run("cross-s",merchantId,"b-statement",null,"cross-s"),/merchant mismatch/);assert.throws(()=>db.sqlite.prepare(sql).run("cross-a",merchantId,null,"b-adjustment","cross-a"),/merchant mismatch/);});

test("RC3.1-6 Pending Adjustment 可核准且重送安全 replay",async()=>{const db=new D1();seedProfile(db);seedStatement(db,{status:"locked"});db.sqlite.prepare("INSERT INTO merchant_settlement_adjustments(id,merchant_id,source_settlement_id,source_statement_id,adjustment_type,deposit_reversal_minor,platform_fee_reversal_minor,offset_reversal_minor,provider_fee_reversal_minor,amount_minor,reason,effective_date,eligible_period_start,review_status,idempotency_key,created_by) VALUES ('review-me',?,'statement-1','statement-1','refund',-30000,-2000,-1500,0,-28000,'pending','2026-09-05','2026-09-05','pending','auto-review','system')").run(merchantId);const body={decision:"approved",confirmed_deposit_reversal_minor:-30000,confirmed_platform_fee_reversal_minor:-2000,confirmed_offset_reversal_minor:-1500,confirmed_provider_fee_reversal_minor:0,reason:"契約與退款資料已確認",confirm_professional_review:true};const request=req("/settlement-adjustments/review-me/review","POST",body,"review-key");let response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,200);response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.headers.get("idempotent-replay"),"true");const row=db.sqlite.prepare("SELECT review_status,amount_minor,reviewed_by FROM merchant_settlement_adjustments WHERE id='review-me'").get();assert.deepEqual([row.review_status,row.amount_minor,row.reviewed_by],["approved",-28000,"admin"]);assert.equal(db.sqlite.prepare("SELECT COUNT(*) n FROM audit_logs WHERE action='merchant_settlement_adjustment_reviewed'").get().n,1);});

test("RC3.1-7 Adjustment 拒絕後不可回 pending，Provider 退費需 reference",async()=>{const db=new D1();seedProfile(db);seedStatement(db,{status:"locked"});const insert="INSERT INTO merchant_settlement_adjustments(id,merchant_id,source_settlement_id,source_statement_id,adjustment_type,amount_minor,reason,effective_date,eligible_period_start,review_status,idempotency_key,created_by) VALUES (?,?, 'statement-1','statement-1','refund',-100,'pending','2026-09-05','2026-09-05','pending',?,'system')";db.sqlite.prepare(insert).run("reject-me",merchantId,"reject-auto");let request=req("/settlement-adjustments/reject-me/review","POST",{decision:"rejected",confirmed_deposit_reversal_minor:-100,confirmed_platform_fee_reversal_minor:0,confirmed_offset_reversal_minor:0,confirmed_provider_fee_reversal_minor:0,reason:"資料不足",confirm_professional_review:true},"reject-key");assert.equal((await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"})).status,200);assert.throws(()=>db.sqlite.prepare("UPDATE merchant_settlement_adjustments SET review_status='pending' WHERE id='reject-me'").run(),/final/);db.sqlite.prepare(insert).run("provider-me",merchantId,"provider-auto");request=req("/settlement-adjustments/provider-me/review","POST",{decision:"approved",confirmed_deposit_reversal_minor:-100,confirmed_platform_fee_reversal_minor:0,confirmed_offset_reversal_minor:0,confirmed_provider_fee_reversal_minor:30,reason:"Provider 退費",confirm_professional_review:true},"provider-key");assert.equal((await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"})).status,400);});

test("RC3.1-8 Adjustment 查詢支援 review_status 與月份",async()=>{const db=new D1();seedProfile(db);seedStatement(db,{status:"locked"});db.sqlite.prepare("INSERT INTO merchant_settlement_adjustments(id,merchant_id,source_settlement_id,source_statement_id,adjustment_type,amount_minor,reason,effective_date,eligible_period_start,review_status,idempotency_key,created_by) VALUES ('listed',?,'statement-1','statement-1','refund',-100,'pending','2026-09-05','2026-09-05','pending','listed','system')").run(merchantId);const request=req("/settlement-adjustments?review_status=pending&effective_month=2026-09&limit=10");const response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,200);assert.equal((await response.json()).items[0].id,"listed");});

test("RC3.1-9 重疊期間與歷史普通對帳被拒絕",async()=>{const db=new D1();seedProfile(db);seedStatement(db,{status:"locked",start:"2026-08-01",end:"2026-08-31"});assert.throws(()=>seedStatement(db,{id:"overlap",start:"2026-08-15",end:"2026-09-15"}),/overlap/);const db2=new D1();seedProfile(db2);seedStatement(db2,{status:"locked",start:"2026-09-01",end:"2026-09-30"});const request=req("/settlements/preview","POST",{merchant_id:merchantId,period_start:"2026-08-01",period_end:"2026-08-31"});const response=await handleSettlementRequest(request,{FINANCE_DB:db2},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,409);assert.equal((await response.json()).code,"HISTORICAL_CORRECTION_REQUIRED");});

test("RC3.1-10 未來 Ledger 不回流過去，Void 不擋替代且連續月份可建立",async()=>{const db=new D1();seedProfile(db,merchantId,"sales_offset_18000");db.sqlite.prepare("INSERT INTO merchant_offset_ledger(id,merchant_id,entry_type,amount_minor,effective_at,idempotency_key,created_by) VALUES ('future',?,'offset_earned',50000,'2026-09-30','future','admin')").run(merchantId);let request=req("/settlements/preview","POST",{merchant_id:merchantId,period_start:"2026-08-01",period_end:"2026-08-31"});let response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal((await response.json()).preview.prior_offset_amount_minor,0);const db2=new D1();seedProfile(db2);seedStatement(db2,{status:"void"});assert.doesNotThrow(()=>seedStatement(db2,{id:"replacement"}));const db3=new D1();seedProfile(db3);seedStatement(db3,{status:"locked"});request=req("/settlements","POST",{merchant_id:merchantId,period_start:"2026-09-01",period_end:"2026-09-30"},"continuous");response=await handleSettlementRequest(request,{FINANCE_DB:db3},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,201);});

test("RC3.1-11 USD 與 Order／Payment 幣別不一致不得取得資格",async()=>{for(const currencies of [["USD","USD"],["TWD","USD"]]){const db=new D1();seedProfile(db);const payment=seedPayment(db,{suffix:currencies.join("-"),orderCurrency:currencies[0],paymentCurrency:currencies[1]});const request=req(`/settlement-sources/${payment.paymentId}`,"PATCH",{collection_role:"platform_deposit",settlement_eligible:true,order_total_amount_minor:1000000,actual_collected_amount_minor:300000,confirm_source_review:true});assert.equal((await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"})).status,422);}});

test("RC3.1-12 嚴格 decimal parser 拒絕三位小數、科學記號與超大值",()=>{assert.equal(decimalMajorToMinor("100.12"),10012);for(const value of ["100.123","1e2","NaN","Infinity","-1","9007199254740991"])assert.equal(decimalMajorToMinor(value),null);});

test("RC3.1-13 同 Statement 同 action 不同 key 不可並行",async()=>{const db=new D1();seedProfile(db);seedStatement(db);db.sqlite.prepare("INSERT INTO merchant_settlement_operations(id,settlement_id,merchant_id,operation_type,operation_scope,idempotency_key,expires_at,created_by) VALUES ('running','statement-1',?,'submit-review','statement-1','first','2099-01-01','admin')").run(merchantId);const request=req("/settlements/statement-1/submit-review","POST",{},"second");const response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,409);assert.equal(db.sqlite.prepare("SELECT status FROM merchant_settlements WHERE id='statement-1'").get().status,"draft");});

test("RC3.1-14 過期 operation 可重新取得並完成",async()=>{const db=new D1();seedProfile(db);seedStatement(db);db.sqlite.prepare("INSERT INTO merchant_settlement_operations(id,settlement_id,merchant_id,operation_type,operation_scope,idempotency_key,expires_at,created_by) VALUES ('expired','statement-1',?,'submit-review','statement-1','retry','2000-01-01','admin')").run(merchantId);const request=req("/settlements/statement-1/submit-review","POST",{},"retry");const response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,200);assert.equal(db.sqlite.prepare("SELECT status FROM merchant_settlement_operations WHERE id='expired'").get().status,"completed");});

test("RC3.1-15 Legacy Finance 以 Asia/Taipei 月份 UTC 邊界統計",async()=>{const db=new D1();seedPayment(db,{suffix:"taipei-summary",paidAt:"2026-08-31T16:30:00.000Z"});const result=await financeSummary(db,new Date("2026-08-31T16:30:00.000Z"));assert.equal(result.payment_count,1);assert.equal(result.month_gross,3000);});
test("RC3.1-16 Migration rollback 保留既有 Finance／Partner／Admin 資料表",()=>{const db=new D1();db.sqlite.exec(readFileSync(new URL("../migrations/rollback/0010_merchant_settlements.down.sql",import.meta.url),"utf8"));for(const table of ["merchants","payments","orders","refunds","partners","admin_users"])assert.ok(db.sqlite.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name=?").get(table));for(const table of ["platform_finance_settings","merchant_settlement_profiles","merchant_settlement_sources","merchant_settlements","merchant_settlement_items","merchant_settlement_adjustments","merchant_offset_ledger","merchant_settlement_events","settlement_document_versions","merchant_settlement_operations","finance_refund_operations"])assert.equal(db.sqlite.prepare("SELECT COUNT(*) n FROM sqlite_master WHERE type='table' AND name=?").get(table).n,0);});

test("RC3.1-17 Create Draft 重送先 replay，不被自身期間重疊阻擋",async()=>{const db=new D1();seedProfile(db);const makeRequest=()=>req("/settlements","POST",{merchant_id:merchantId,period_start:"2026-08-01",period_end:"2026-08-31"},"create-replay");let request=makeRequest();let response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,201);const first=await response.json();request=makeRequest();response=await handleSettlementRequest(request,{FINANCE_DB:db},new URL(request.url),{}, {admin_user_id:"admin"});assert.equal(response.status,201);assert.equal(response.headers.get("idempotent-replay"),"true");assert.equal((await response.json()).id,first.id);assert.equal(db.sqlite.prepare("SELECT COUNT(*) n FROM merchant_settlements").get().n,1);});
